<template><view class="service-card" :class="{horizontal}" @click="go('service/detail',{id:item.id})" role="button" :aria-label="item.title"><GameArt class="service-cover" :variant="horizontal?'horizontal':'cover'" :game="item.game" :src="images(item.images)[0]"><text v-if="!horizontal" class="art-label">{{item.game}}</text></GameArt><view class="service-info"><text class="service-name">{{item.title}}</text><text class="service-desc">{{item.itemCategory}} · {{item.pricingMode==='UNIT'?item.availableQuantity:item.quantity}} 件 · {{gameServerLabel(item)}}</text><view class="price-row"><text class="price"><text class="currency">¥</text>{{money(item.priceCents)}}</text><text class="muted tiny">{{item.pricingMode==='UNIT'?' / 件':' / 整批'}}</text><text v-if="item.sales" class="sales-count">{{item.sales}} 人下单</text></view><view v-if="!horizontal" class="seller-row" role="button" :aria-label="'查看'+item.nickname+'的主页'" @click.stop="go('shop/index',{id:item.ownerId})"><GameArt avatar :size="20" :type="item.avatar" :src="item.avatar?.startsWith('/')?item.avatar:''" /><text class="seller-name">{{item.shopName||item.nickname}}</text><text v-if="item.shopStatus==='APPROVED'&&item.realnameStatus==='VERIFIED'" class="tag tiny">认证店铺</text></view></view></view></template>
<script setup>import {gameServerLabel} from '../lib/playerTrade';import GameArt from './GameArt.vue';import {go,money,images} from '../lib/api';defineProps({item:Object,horizontal:Boolean})</script>
